public boolean isPrime(int n) {
    if (n <= 1) return false;
    for (int i = 2; i <= Math.sqrt(n); i++) {
        if (n % i == 0) return false;
    }
    return true;
}

public int factorial(int n) {
    if (n == 0) return 1;
    return n * factorial(n - 1);
}

